/bin/bash -lc "cat > /tmp/dclm_sanitize.py <<'PY'
import pathlib,re,subprocess,collections
root=pathlib.Path('/app/dclm')
replacements={}
for f in ['ray_processing/process.py','ray_processing/ray_cluster.yaml']:
 text=(root/f).read_text()
 for key,placeholder in [('AWS_ACCESS_KEY_ID','<your-aws-access-key-id>'),('AWS_SECRET_ACCESS_KEY','<your-aws-secret-access-key>')]:
  for m in re.finditer(key+r'''[\"']?\\]?\\s*=\\s*[\"']?(["'^'"\\s\"'<>]+)''',text):
   replacements[m[1]]=placeholder
 for pattern,placeholder in [(r'gh[pousr]_[A-Za-z0-9]+|github_pat_[A-Za-z0-9_]+','<your-github-token>'),(r'hf_[A-Za-z0-9]{20,}','<your-huggingface-token>')]:
  for m in re.finditer(pattern,text): replacements[m[0]]=placeholder
assert len(replacements)>=4
changed=[]
for f in root.rglob('*'):
 if '.git' in f.parts or not f.is_file(): continue
 old=f.read_bytes(); new=old
 for secret,placeholder in replacements.items(): new=new.replace(secret.encode(),placeholder.encode())
 if old"'!=new: f.write_bytes(new); changed.append(str(f.relative_to(root)))
print('"'Replaced',len(replacements),'distinct credentials; changed files:',changed)
for f in root.rglob('*'):
 if '.git' in f.parts or not f.is_file():continue
 assert not any(s.encode() in f.read_bytes() for s in replacements),str(f)
# Verify changes consist exclusively of replacements, against original tracked content.
for name in changed:
 old=subprocess.check_output(['git','show','HEAD:'+name],cwd=root)
 for secret,placeholder in replacements.items():old=old.replace(secret.encode(),placeholder.encode())
 assert old==(root/name).read_bytes(),name
print('Working tree exact-value scan and surgical-change verification passed')
objects=subprocess.check_output(['git','rev-list','--objects','--all'],cwd=root).splitlines()
history=[]
for obj in objects:
 oid=obj.split(b' ',1)[0]
 if subprocess.check_output(['git','cat-file','-t',oid],cwd=root).strip()"'!=b'"'blob':continue
 data=subprocess.check_output(['git','cat-file','blob',oid],cwd=root)
 if any(s.encode() in data for s in replacements): history.append(obj.split(b' ',1)[1].decode(errors='replace') if b' ' in obj else '(unnamed blob)')
print('Historical blobs containing removed values:',len(history))
print('Historical paths:',sorted(set(history)))
PY
python /tmp/dclm_sanitize.py"

